{
    var proj = "";
    var node = (BaseNode)t;
    while (node != null) { if (node is Project pp) { proj = pp.Name; break; } node = node.Parent; }
    if (proj.Contains("Core") || proj.Contains("Services") || proj.Contains("Api"))
    {
        Console.WriteLine($"  {proj} / {t.Name} - HasError: {t.Children.OfType<Error>().Any()}");
    }
}

// Check for MSB3202 or dependency resolution errors
Console.WriteLine("\n=== All messages containing 'could not be resolved' or 'failed' ===");
var msgs = build.FindChildrenRecursive<Message>();
foreach (var m in msgs.Where(m => m.Text != null && (m.Text.Contains("could not be resolved") || m.Text.Contains("was not found")) && !m.Text.Contains("Newtonsoft.Json 2.2")))
{
    Console.WriteLine($"  {m.Text}");
}
