        Console.WriteLine($"  [{node.GetType().Name}] {(node is NamedNode nn ? nn.Name : node.ToString()?.Substring(0, Math.Min(80, node.ToString()?.Length ?? 0)))}");
        node = node.Parent;
    }
}

